const body = $input.item.json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value || {};

// STATUS mesajlarını filtrele (delivery/read receipts)
if (!value.messages || value.messages.length === 0) {
  return []; // Boş döndür → akış durur
}

const msg = value.messages[0];
const message_id = msg.id || '';
const from = msg.from || '';
const type = msg.type || '';
const interactive_id = msg.interactive?.list_reply?.id || msg.interactive?.button_reply?.id || '';
const text_raw = msg.text?.body || msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
const timestamp_ms = msg.timestamp ? Number(msg.timestamp) * 1000 : Date.now();
const nowISO = new Date(timestamp_ms).toISOString();
const session_id = 'whatsapp:' + from;

return { json: { message_id, from, type, interactive_id, text_raw, timestamp_ms, nowISO, session_id } };

const parsed = $('Parse WhatsApp').item.json;

const byId = (($('Sheets Get Session').first() || {}).json) || {};
const byPatient = ($('Sheets Get Session By Patient Phone').first() || {}).json || {};
const byBooker = ($('Sheets Get Session By Booker Phone').first() || {}).json || {};

function isValidRow(r) {
  return r && r.session_id && r.state && String(r.state).trim() !== '';
}

// FIX A2: Primary key = session_id. Fallback'ler sadece yoksa devreye girer.
// "Başkası için" akışlarında farklı patient'larla çakışma önlenir.
const existing = isValidRow(byId) ? byId
  : (isValidRow(byBooker) ? byBooker
  : (isValidRow(byPatient) ? byPatient
  : {}));

// Idempotency
if (existing.last_message_id && existing.last_message_id === parsed.message_id) {
  return { json: { _stop: true } };
}

// FIX A5: default state = INIT (not NEW → removes double welcome)
const defaults = {
  session_id: parsed.session_id,
  user_id: parsed.from,
  booked_by_phone: parsed.from,
  patient_phone: parsed.from,
  pending_patient_phone: '',
  otp_code: '',
  otp_expires_at: '',
  otp_attempts: 0,
  otp_request_count: 0,
  otp_locked_until: '',
  state: 'INIT',
  service_id: '',
  doctor_id: '',
  selected_slot_start: '',
  selected_slot_end: '',
  hold_event_id: '',
  hold_expires_at: '',
  patient_name: '',
  flow_type: '',
  patient_notes: '',
  complaint_text: '',
  complaint_tag: '',
  last_message_id: '',
  updated_at: ''
};

const session = isValidRow(existing) ? { ...defaults, ...existing } : { ...defaults };

session.otp_attempts = Number(session.otp_attempts || 0);
session.otp_request_count = Number(session.otp_request_count || 0);
session.pending_patient_phone = (session.pending_patient_phone || '').toString();
session.otp_code = (session.otp_code || '').toString();
session.otp_expires_at = (session.otp_expires_at || '').toString();
session.otp_locked_until = (session.otp_locked_until || '').toString();

return { json: { ...parsed, session } };

const parsed = $('Parse WhatsApp').first().json;
const sessionData = $('Upsert+Idempotency').first().json;

const interactive_id = parsed.interactive_id || '';
const text_raw = parsed.text_raw || '';
const st = (sessionData.session && sessionData.session.state) ? sessionData.session.state.toString().trim() : '';

let event = { kind: 'text', value: '' };

// ── 1. Interactive (button / list) events ──
if (interactive_id.startsWith('svc|')) {
  event = { kind: 'svc', value: interactive_id.substring(4) };
} else if (interactive_id.startsWith('doc|')) {
  event = { kind: 'doc', value: interactive_id.substring(4) };
} else if (interactive_id.startsWith('slot|')) {
  event = { kind: 'slot', value: interactive_id };
} else if (interactive_id.startsWith('day|')) {
  event = { kind: 'day', value: interactive_id.substring(4) };
} else if (interactive_id === 'btn_confirm') {
  event = { kind: 'confirm', value: 'confirm' };
} else if (interactive_id === 'btn_change') {
  event = { kind: 'change', value: 'change' };
} else if (interactive_id === 'btn_cancel') {
  event = { kind: 'cancel', value: 'cancel' };
} else if (interactive_id === 'btn_reminder_ok') {
  event = { kind: 'reminder_ok', value: 'reminder_ok' };
} else if (interactive_id === 'btn_reminder_change') {
  event = { kind: 'change', value: 'change' };
} else if (interactive_id === 'btn_reminder_cancel') {
  event = { kind: 'cancel', value: 'cancel' };
} else if (interactive_id === 'btn_resend_otp') {
  event = { kind: 'resend_otp', value: 'resend_otp' };
} else if (interactive_id === 'btn_book') {
  event = { kind: 'book', value: 'book' };
} else if (interactive_id === 'btn_for_self') {
  event = { kind: 'for_self', value: 'self' };
} else if (interactive_id === 'btn_for_other') {
  event = { kind: 'for_other', value: 'other' };
} else {
  // ── 2. Pure text — state-aware heuristics ──
  const t = (text_raw || '').trim();
  const tl = t.toLowerCase().replace(/[ıİ]/g, m => m === 'ı' ? 'i' : 'i');
  event = { kind: 'text', value: t };

  // FIX A1: AWAITING_OTP resend via text (was out of scope)
  if (st === 'AWAITING_OTP') {
    if (/^(tekrar|yeniden|resend|kod tekrar|kodu tekrar|kodu yeniden)$/i.test(tl)) {
      event = { kind: 'resend_otp', value: 'resend_otp' };
    }
    // "yanlış numara" / "geri dön" → back to phone input
    else if (/yanl[iı][sş].*numara|numara.*yanl[iı][sş]|geri\s*d[oö]n/i.test(t)) {
      event = { kind: 'back_to_phone', value: 'back_to_phone' };
    }
  }

  // FIX C1: AWAITING_FOR_WHOM — text-based for_self / for_other detection
  else if (st === 'AWAITING_FOR_WHOM') {
    if (/^(ben|kendim|benim|bana|benim\s*i[cç]in|kendim\s*i[cç]in)$/i.test(tl) ||
        /benim\s*i[cç]in|kendim\s*i[cç]in/i.test(tl)) {
      event = { kind: 'for_self', value: 'self' };
    } else if (/annem|babam|e[sş]im|[cç]ocu[gğ]|ba[sş]kas[iı]|arkada[sş]|yak[iı]n|abla|a[gğ]abey|karde[sş]|torun|dede|nine|ba[sş]ka\s*biri/i.test(t)) {
      event = { kind: 'for_other', value: 'other' };
    }
    // else stays as text → fallback will re-show buttons
  }

  // FIX C4: HELD — text-based confirm/change/cancel
  else if (st === 'HELD') {
    if (/^(evet|tamam|onay|onayla|ok|olur|kabul)$/i.test(tl) ||
        /onayl[iı]yorum|onay\s*ver/i.test(tl)) {
      event = { kind: 'confirm', value: 'confirm' };
    } else if (/de[gğ]i[sş]|ba[sş]ka\s*saat|ba[sş]ka\s*g[uü]n/i.test(t)) {
      event = { kind: 'change', value: 'change' };
    } else if (/iptal|vazge[cç]|istemiyorum/i.test(t)) {
      event = { kind: 'cancel', value: 'cancel' };
    }
  }

  // FIX C5: AWAITING_PATIENT_PHONE — "kendim" shortcut
  else if (st === 'AWAITING_PATIENT_PHONE') {
    if (/^(kendim|benim|bana|benim\s*i[cç]in)$/i.test(tl)) {
      event = { kind: 'switch_to_self', value: 'self' };
    }
  }

  // Generic commands from INIT / NEW / ACTIVE_EXISTS
  if (st === 'INIT' || st === 'NEW' || st === 'ACTIVE_EXISTS') {
    if (/^(iptal|iptal\s*et)$/i.test(tl)) { event = { kind: 'cancel', value: 'cancel' }; }
    else if (/de[gğ]i[sş]tir/i.test(tl)) { event = { kind: 'change', value: 'change' }; }
    else if (/randevu\s*al/i.test(tl)) { event = { kind: 'book', value: 'book' }; }
    else if (/^(men[uü]|menu|ba[sş]a\s*d[oö]n)$/i.test(tl)) { event = { kind: 'text', value: 'menü' }; }
  }
}

const output = {
  message_id: parsed.message_id,
  from: parsed.from,
  type: parsed.type,
  interactive_id: parsed.interactive_id || '',
  text_raw: parsed.text_raw || '',
  timestamp_ms: parsed.timestamp_ms,
  nowISO: parsed.nowISO,
  session_id: sessionData.session_id,
  session: sessionData.session,
  event
};

return [{ json: output }];

// Google Sheets'ten gelen hizmetleri al
const services = $('Sheets Read Services').all().map(item => item.json);

// AI için okunabilir bir liste oluştur
// Örnek Çıktı: "1 | Diş Çekimi | tags: ağrı, çekim"
const services_lines = services.map(s => {
    // service_id'yi zorla metne çevir (toString)
    const id = s.service_id ? s.service_id.toString() : '';
    const name = s.service_name || '';
    const tags = s.complaint_tags || '';
    return `${id} | ${name} | tags:${tags}`;
}).join('\n');

return { json: { ...$input.item.json, services_lines } };

// KVKK + Önce Muayene: servis her zaman muayene_001
const sourceData = $('Build Services Lines').first().json || $input.item.json;

const aiResponseText = $input.item.json.text || '{}';
let ai = {};
try { ai = JSON.parse(aiResponseText); } catch(e) { ai = {}; }

const session = { ...(sourceData.session || {}) };

session.complaint_text = (sourceData.event && sourceData.event.value) ? sourceData.event.value : (session.complaint_text || '');

const summary = ai.medical_summary || ai.summary || ai.complaint_summary || '';
if (summary) session.patient_notes = summary;

session.service_id = 'muayene_001';
session.state = 'SERVICE_SELECTED';

if (ai.urgency) session.complaint_tag = String(ai.urgency);

session.updated_at = new Date().toISOString();

return { json: { ...sourceData, session, ai } };

const services = $('Sheets Read Services').all().map(item => item.json);
const rows = services.map(s => ({
  id: 'svc|' + s.service_id,
  title: s.service_name.substring(0, 24),
  description: (s.description || '').substring(0, 72)
}));
const payload = {
  messaging_product: 'whatsapp',
  to: $input.item.json.from,
  type: 'interactive',
  interactive: {
    type: 'list',
    header: {
      type: 'text',
      text: 'Hizmet Seçin'
    },
    body: {
      text: 'Hangi işlem için randevu?'
    },
    action: {
      button: 'Hizmetleri Gör',
      sections: [{
        title: 'Available Services',
        rows
      }]
    }
  }
};
return { json: payload };

const items = $input.all();
if (items.length === 0) return [];

const allDoctors = $('Sheets Read Doctors').all().map(i => i.json);

const unique = [];
const seen = new Set();
for (const d of allDoctors) {
  const id = d.doctor_id ? d.doctor_id.toString() : '';
  if (!id || seen.has(id)) continue;
  // Sadece aktif doktorlar
  if (d.is_active === false || d.is_active === 'false') continue;
  unique.push(d);
  seen.add(id);
}

return unique.slice(0, 10).map(doc => ({
  json: { ...items[0].json, doctor: doc }
}));

const items = $input.all();
const doctors = items.map(item => item.json.doctor);

// WhatsApp limiti: Toplam satır sayısı 10'u geçemez
const limitedDoctors = doctors.slice(0, 10);

const rows = limitedDoctors.map(d => ({
  id: 'doc|' + d.doctor_id,
  title: d.doctor_name.substring(0, 24), // Karakter sınırı koruması
  description: (d.specialization || '').substring(0, 72)
}));

const payload = {
  messaging_product: 'whatsapp',
  to: items[0].json.from,
  type: 'interactive',
  interactive: {
    type: 'list',
    header: { type: 'text', text: 'Doktor Seçin' },
    body: { text: 'Şikayetinize yardımcı olabilecek doktorlarımız aşağıdadır:' },
    action: {
      button: 'Doktorları Gör',
      sections: [{ title: 'Müsait Doktorlar', rows }]
    }
  }
};

return { json: payload };

// FIX A1: $input sonrası Sheets node session'ı siler. 
// Derive Event'ten oku, event.value'dan doctor_id al.
const deriveData = $('Derive Event').first().json;
const data = { ...deriveData, ...$input.item.json };
const session = deriveData.session || {};

// doctor_id: önce session, sonra event (yeni seçim), sonra Sheets response
const doctor_id = session.doctor_id || deriveData.event?.value || data.doctor_id || '';

if (!doctor_id) {
  return { json: { ...data, session, _stop: true, error: 'No doctor_id in Resolve Doctor+Duration' } };
}

const doctors = $('Sheets Read Doctors').all().map(i => i.json);
const doctor = doctors.find(d => d.doctor_id === doctor_id);

if (!doctor) {
  return { json: { ...data, session, _stop: true, error: 'Doctor not found: ' + doctor_id } };
}

const service_id = session.service_id || data.service_id || '';
const services = $('Sheets Read Services').all().map(i => i.json);
const service = services.find(s => s.service_id === service_id);
const duration_min = parseInt(service?.duration_min, 10) || 30;
const buffer_min = parseInt(service?.buffer_min, 10) || 0;

return { json: {
  ...data,
  session: { ...session, doctor_id },
  event: deriveData.event,
  doctor,
  service_id,
  service_name: service?.service_name || 'Muayene',
  slot_duration_min: duration_min,
  buffer_min,
  calendar_id: doctor.calendar_id,
  from: deriveData.from || session.user_id || ''
} };

const free_slots = $input.item.json.free_slots || [];
const prev = $('Resolve Doctor+Duration').first().json;
const doctor_id = prev.session?.doctor_id || prev.doctor_id || '';
const from = prev.from || prev.session?.user_id || $('Parse WhatsApp').first().json.from || '';
const event = prev.event || $input.item.json.event || {};

const tz = 'Europe/Istanbul';
const toDayKey = (iso) => new Date(iso).toLocaleDateString('en-CA', { timeZone: tz });
const selectedDay = event.kind === 'day' ? event.value : '';

const WA_MAX_ROWS = 10;

function buildListPayload(to, header, body, buttonLabel, sections) {
  return {
    messaging_product: 'whatsapp',
    to,
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: header },
      body: { text: body },
      action: { button: buttonLabel, sections }
    }
  };
}

if (!selectedDay) {
  // ── GÜN LİSTESİ (max 20 gün → 2 mesaj) ──
  const dayMap = new Map();
  free_slots.forEach(slot => {
    const dayKey = toDayKey(slot.start);
    if (!dayMap.has(dayKey)) dayMap.set(dayKey, new Date(slot.start));
  });

  const allDays = Array.from(dayMap.entries()).slice(0, 20);
  const dayRows = allDays.map(([dayKey, date]) => {
    const label = date.toLocaleDateString('tr-TR', {
      weekday: 'long', day: '2-digit', month: 'short', timeZone: tz
    });
    return { id: 'day|' + dayKey, title: label.substring(0, 24), description: 'Uygun gün' };
  });

  const payloads = [];
  const batch1 = dayRows.slice(0, WA_MAX_ROWS);
  if (batch1.length > 0) {
    payloads.push(buildListPayload(from,
      'Gün Seçin 📅',
      allDays.length > WA_MAX_ROWS
        ? 'Uygun bir gün seçin (sayfa 1/' + Math.ceil(allDays.length / WA_MAX_ROWS) + '):'
        : 'Uygun bir gün seçin:',
      'Günleri Gör',
      [{ title: 'Uygun Günler', rows: batch1 }]
    ));
  }

  const batch2 = dayRows.slice(WA_MAX_ROWS, WA_MAX_ROWS * 2);
  if (batch2.length > 0) {
    payloads.push(buildListPayload(from,
      'Gün Seçin 📅',
      'Uygun bir gün seçin (sayfa 2/' + Math.ceil(allDays.length / WA_MAX_ROWS) + '):',
      'Diğer Günler',
      [{ title: 'Diğer Günler', rows: batch2 }]
    ));
  }

  // Return multiple items — WA Send Slots iterates over each
  return payloads.map(p => ({ json: { ...prev, free_slots, payload: p } }));
}

// ── SAAT LİSTESİ (max 20 slot → 2 mesaj) ──
const session = { ...prev.session };
session.state = 'DAY_SELECTED';
session.updated_at = new Date().toISOString();

const filteredSlots = free_slots.filter(slot => toDayKey(slot.start) === selectedDay);

if (filteredSlots.length === 0) {
  const payload = {
    messaging_product: 'whatsapp',
    to: from,
    type: 'text',
    text: { body: '😔 Seçtiğiniz gün için uygun saat bulunamadı.\nLütfen başka bir gün seçin.' }
  };
  return [{ json: { ...prev, session, free_slots, payload } }];
}

const allSlotRows = filteredSlots.slice(0, 20).map(slot => {
  const startDate = new Date(slot.start);
  const hhmm = startDate.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit', timeZone: tz });
  const ddmmm = startDate.toLocaleDateString('tr-TR', { day: '2-digit', month: 'short', weekday: 'short', timeZone: tz });
  return { id: 'slot|' + slot.start + '|' + doctor_id, title: hhmm, description: ddmmm };
});

const payloads = [];
const batch1 = allSlotRows.slice(0, WA_MAX_ROWS);
if (batch1.length > 0) {
  payloads.push(buildListPayload(from,
    'Saat Seçin 🕐',
    allSlotRows.length > WA_MAX_ROWS
      ? 'Uygun saati seçin (sayfa 1/' + Math.ceil(allSlotRows.length / WA_MAX_ROWS) + '):'
      : 'Seçtiğiniz gün için uygun saati seçin:',
    'Saatleri Gör',
    [{ title: 'Uygun Saatler', rows: batch1 }]
  ));
}

const batch2 = allSlotRows.slice(WA_MAX_ROWS, WA_MAX_ROWS * 2);
if (batch2.length > 0) {
  payloads.push(buildListPayload(from,
    'Saat Seçin 🕐',
    'Uygun saati seçin (sayfa 2/' + Math.ceil(allSlotRows.length / WA_MAX_ROWS) + '):',
    'Diğer Saatler',
    [{ title: 'Diğer Saatler', rows: batch2 }]
  ));
}

return payloads.map(p => ({ json: { ...prev, session, free_slots, payload: p } }));

const calEvent = $input.item.json;
const event_id = calEvent.id || '';
const session = { ...$('Derive Slot Event').item.json.session };

session.state = 'HELD';
session.hold_event_id = event_id;

// FIX E2: Hold 5dk, Calendar end_time kullan
const holdExpires = new Date(Date.now() + 5 * 60000);
session.hold_expires_at = holdExpires.toISOString();
session.updated_at = new Date().toISOString();

return { json: { ...$('Derive Slot Event').item.json, session } };

const session = $('Set HELD + TTL').first().json.session || {};
const doctor = $('Set HELD + TTL').first().json.doctor || {};
const from = $('Parse WhatsApp').first().json.from;

const slotStart = session.selected_slot_start || '';
let dateText = '';
if (slotStart) {
  const dt = new Date(slotStart);
  dateText = dt.toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

const doctorName = doctor.doctor_name || '';
const complaint = session.complaint_text || '';

let bodyText = '⏱️ Randevunuz 5 dk rezerve edildi!\n\n';
if (doctorName) bodyText += `👨‍⚕️ Doktor: ${doctorName}\n`;
if (dateText) bodyText += `📅 Tarih: ${dateText}\n`;
if (complaint) bodyText += `📝 Şikayet: ${complaint}\n`;
bodyText += '\nLütfen onaylayın:';

const payload = {
  messaging_product: 'whatsapp',
  to: from,
  type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: bodyText },
    action: {
      buttons: [
        { type: 'reply', reply: { id: 'btn_confirm', title: '✅ Onayla' } },
        { type: 'reply', reply: { id: 'btn_change', title: '🔄 Değiştir' } },
        { type: 'reply', reply: { id: 'btn_cancel', title: '❌ İptal' } }
      ]
    }
  }
};

return { json: payload };

// Randevu satırı oluştur — Türkçe, okunabilir format
const rdfc = $('Resolve Doctor For Confirm').first().json;
const session = rdfc.session || {};
const doctor = rdfc.doctor || {};
const calEvent = $input.item.json; // Calendar response

const tz = 'Europe/Istanbul';
const now = new Date();

function fmtFull(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleString('tr-TR', { 
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit', timeZone: tz 
  });
}

// ID
const ts = Math.floor(now.getTime() / 1000);
const rand = Math.random().toString(36).substring(2, 6).toUpperCase();

// Süre
const start = new Date(session.selected_slot_start || now);
const end = new Date(session.selected_slot_end || now);
const sure_dk = Math.round((end - start) / 60000) || 30;

// Telefon numaralarındaki ".0" suffix'ini temizle
const cleanPhone = (p) => (p || '').toString().replace(/\.0$/, '');

return { json: {
  randevu_id: 'APT-' + ts + '-' + rand,
  durum: 'ONAYLANDI',
  hasta_adi: session.patient_name || '',
  hasta_tel: cleanPhone(session.patient_phone || session.user_id),
  doktor: doctor.doctor_name || '',
  hizmet: rdfc.service_name || '',
  tarih_saat: fmtFull(session.selected_slot_start),
  bitis: fmtFull(session.selected_slot_end),
  sure_dk,
  sikayet: session.complaint_text || '',
  hasta_notu: session.patient_notes || '',
  kaynak: 'whatsapp',
  randevu_alan: cleanPhone(session.booked_by_phone || session.user_id),
  calendar_event_id: calEvent.id || session.hold_event_id || '',
  olusturma: fmtFull(now.toISOString()),
} };

const from = $('Parse WhatsApp').first().json.from;
const doctor = $('Resolve Doctor For Confirm').first().json.doctor || {};
const session = $('Resolve Doctor For Confirm').first().json.session || {};

const slotStart = session.selected_slot_start || '';
let dateText = '';
if (slotStart) {
  const dt = new Date(slotStart);
  dateText = dt.toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul', weekday: 'long', day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

const doctorName = doctor.doctor_name || 'Doktor';
const patientName = session.patient_name || '';
const complaint = session.complaint_text || '';

let body = '✅ Randevunuz onaylandı!\n\n';
if (patientName) body += `👤 Hasta: ${patientName}\n`;
body += `👨‍⚕️ Doktor: ${doctorName}\n`;
if (dateText) body += `📅 Tarih: ${dateText}\n`;
if (complaint) body += `📝 Şikayet: ${complaint}\n`;
body += '\nRandevu gününüz hayırlı olsun! 🦷';

const payload = {
  messaging_product: 'whatsapp',
  to: from,
  type: 'text',
  text: { body }
};

return { json: payload };

// FIX A2: Sheets Update After Slot session'ı sildi.
// Derive Slot Event'ten oku — o zaman session.doctor_id var.
const data = $('Derive Slot Event').first().json;
