const prev = $('Resolve Doctor+Duration').first().json;
const doctor = prev.doctor || {};
const SLOT_INTERVAL = parseInt(doctor.slot_interval_min || '30', 10);
const LEAD_TIME_MIN = 60;

// Calendar events → busy intervals (boş olabilir)
let calEvents = [];
try {
  const items = $input.all();
  calEvents = items.map(i => i.json).filter(e => e && typeof e === 'object');
} catch(e) { /* calendar boş */ }

const busyTimes = calEvents
  .filter(e => (e.start?.dateTime || e.start?.date || e.start) && (e.end?.dateTime || e.end?.date || e.end))
  .map(e => ({
    start: new Date(e.start?.dateTime || e.start?.date || e.start),
    end: new Date(e.end?.dateTime || e.end?.date || e.end)
  }));

function isSlotBusy(s, e) {
  return busyTimes.some(b => s < b.end && e > b.start);
}

function h(val, def) {
  if (!val) return def;
  return parseInt(val.toString().split(':')[0], 10);
}

const WS = h(doctor.work_start, 9);
const WE = h(doctor.work_end, 18);
const LS = h(doctor.lunch_start, 12);
const LE = h(doctor.lunch_end, 13);
const workDays = (doctor.working_days || '1,2,3,4,5').split(',').map(Number);
const TZ = 3;
const free_slots = [];
const nowUTC = new Date();
const earliest = new Date(nowUTC.getTime() + LEAD_TIME_MIN * 60000);

for (let d = 0; d < 14 && free_slots.length < 280; d++) {
  const trMidnightUTC = new Date(Date.UTC(
    nowUTC.getUTCFullYear(), nowUTC.getUTCMonth(), nowUTC.getUTCDate() + d,
    -TZ, 0, 0, 0
  ));
  const trDow = new Date(trMidnightUTC.getTime() + TZ * 3600000).getUTCDay();
  if (!workDays.includes(trDow === 0 ? 7 : trDow)) continue;

  const startUTC = new Date(trMidnightUTC.getTime() + WS * 3600000);
  const endUTC   = new Date(trMidnightUTC.getTime() + WE * 3600000);
  const lunchS   = new Date(trMidnightUTC.getTime() + LS * 3600000);
  const lunchE   = new Date(trMidnightUTC.getTime() + LE * 3600000);

  let cur = new Date(startUTC);
  while (cur < endUTC) {
    const slotEnd = new Date(cur.getTime() + SLOT_INTERVAL * 60000);
    if (cur < lunchE && slotEnd > lunchS) { cur = new Date(lunchE); continue; }
    if (cur >= earliest && !isSlotBusy(cur, slotEnd)) {
      free_slots.push({ start: cur.toISOString(), end: slotEnd.toISOString() });
    }
    cur = new Date(cur.getTime() + SLOT_INTERVAL * 60000);
  }
}

return { json: { ...prev, free_slots, event: prev.event || {} } };

