const crypto = require('crypto');
const from = $('Parse WhatsApp').first().json.from;
const session = { ...$input.item.json.session };
const raw = ($input.item.json.text_raw || $input.item.json.event?.value || '').toString();
const digits = raw.replace(/\D/g, '');
const now = new Date();

function maskPhone(p) {
  const s = (p || '').toString();
  if (s.length <= 4) return s;
  return s.slice(0, 2) + '****' + s.slice(-4);
}

function hashOTP(code) {
  return crypto.createHash('sha256').update(code.toString()).digest('hex');
}

// FIX D6: Replay guard — if already past AWAITING_OTP, ignore
if (session.state !== 'AWAITING_OTP') {
  const payload = {
    messaging_product: 'whatsapp',
    to: from,
    type: 'text',
    text: { body: '✅ Doğrulama zaten tamamlanmış.\nŞikayetinizi/işleminizi yazabilirsiniz.' }
  };
  return { json: { ...$input.item.json, session, payload } };
}

// Lock kontrolü
if (session.otp_locked_until) {
  const lockDt = new Date(session.otp_locked_until);
  if (lockDt > now) {
    const remaining = Math.ceil((lockDt - now) / 60000);
    const payload = {
      messaging_product: 'whatsapp',
      to: from,
      type: 'text',
      text: { body: `⛔ Çok fazla hatalı deneme. ${remaining} dakika sonra tekrar deneyin veya "menü" yazın.` }
    };
    return { json: { ...$input.item.json, session, payload } };
  }
  // FIX D2: Lock süresi doldu → OTP'yi invalidate et, resend'e zorla
  session.otp_code = '';
  session.otp_expires_at = '';
  session.otp_locked_until = '';
  session.otp_attempts = 0;
  session.updated_at = now.toISOString();
  const payload = {
    messaging_product: 'whatsapp',
    to: from,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: '🔓 Kilit süresi doldu. Güvenlik için yeni kod gerekli.' },
      action: { buttons: [{ type: 'reply', reply: { id: 'btn_resend_otp', title: '🔁 Yeni Kod Gönder' } }] }
    }
  };
  return { json: { ...$input.item.json, session, payload } };
}

// Format kontrolü
if (!/^\d{6}$/.test(digits)) {
  const payload = {
    messaging_product: 'whatsapp',
    to: from,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: '🔐 Lütfen 6 haneli doğrulama kodunu yazın.\nKod gelmezse tekrar gönderebilirim.' },
      action: { buttons: [{ type: 'reply', reply: { id: 'btn_resend_otp', title: '🔁 Kodu Tekrar Gönder' } }] }
    }
  };
  return { json: { ...$input.item.json, session, payload } };
}

// Code/expiry yoksa
if (!session.otp_code || !session.otp_expires_at) {
  const payload = {
    messaging_product: 'whatsapp',
    to: from,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: 'Kod bulunamadı veya süresi doldu. Tekrar gönderelim mi?' },
      action: { buttons: [{ type: 'reply', reply: { id: 'btn_resend_otp', title: '🔁 Kodu Tekrar Gönder' } }] }
    }
  };
  session.state = 'AWAITING_OTP';
  session.updated_at = now.toISOString();
  return { json: { ...$input.item.json, session, payload } };
}

const exp = new Date(session.otp_expires_at);
if (exp <= now) {
  session.otp_code = '';
  session.otp_expires_at = '';
  session.otp_attempts = 0;
  session.state = 'AWAITING_OTP';
  session.updated_at = now.toISOString();
  const payload = {
    messaging_product: 'whatsapp',
    to: from,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: '⏳ Kodun süresi dolmuş. Tekrar gönderelim mi?' },
      action: { buttons: [{ type: 'reply', reply: { id: 'btn_resend_otp', title: '🔁 Kodu Tekrar Gönder' } }] }
    }
  };
  return { json: { ...$input.item.json, session, payload } };
}

// FIX D1: Hash karşılaştırma (plaintext yerine)
const inputHash = hashOTP(digits);
if (inputHash !== session.otp_code.toString()) {
  session.otp_attempts = Number(session.otp_attempts || 0) + 1;
  session.updated_at = now.toISOString();

  if (session.otp_attempts >= 3) {
    const lock = new Date(now.getTime() + 15 * 60 * 1000);
    session.otp_locked_until = lock.toISOString();
    // FIX D2: Lock'ta OTP'yi de invalidate et
    session.otp_code = '';
    session.otp_expires_at = '';
    const payload = {
      messaging_product: 'whatsapp',
      to: from,
      type: 'text',
      text: { body: '⛔ 3 kez hatalı kod girildi. Güvenlik nedeniyle 15 dakika kilitlendi.' }
    };
    return { json: { ...$input.item.json, session, payload } };
  }

  const remaining = 3 - session.otp_attempts;
  const payload = {
    messaging_product: 'whatsapp',
    to: from,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: `❌ Kod hatalı. ${remaining} deneme hakkınız kaldı.\nKod gelmezse tekrar gönderebilirim.` },
      action: { buttons: [{ type: 'reply', reply: { id: 'btn_resend_otp', title: '🔁 Kodu Tekrar Gönder' } }] }
    }
  };
  return { json: { ...$input.item.json, session, payload } };
}

// ✅ OTP doğru!
